/* global additionalScope */
// Optional host-provided additionalScope is guarded below when it is absent.
(async () => {
  try {
    // =========================================================
    // EXPORT MODE
    //   "all" | "details_ing" | "details_school" | "sum"
    // =========================================================
    const modeFromState =
      (typeof st_po_export_mode !== "undefined" && st_po_export_mode?.value) ? String(st_po_export_mode.value)
        : null;

    const modeFromScope =
      (typeof additionalScope !== "undefined" && additionalScope?.mode) ? String(additionalScope.mode)
        : null;

    const mode = (modeFromState || modeFromScope || "all").trim().toLowerCase();

    const INCLUDE = {
      detailsIng: mode === "all" || mode === "details_ing",
      detailsSchool: mode === "all" || mode === "details_school",
      sum: mode === "all" || mode === "sum",
    };

    if (!INCLUDE.detailsIng && !INCLUDE.detailsSchool && !INCLUDE.sum) {
      utils.showNotification({
        title: "Mode xuất không hợp lệ",
        description: `mode=${mode}`,
        type: "error",
      });
      return;
    }

    // =========================================================
    // LIB CHECKS
    // =========================================================
    if (typeof ExcelJS === "undefined" || typeof JSZip === "undefined") {
      utils.showNotification({
        title: "Thiếu thư viện",
        description: "Thêm exceljs và jszip trong App → Libraries.",
        type: "error",
      });
      return;
    }

    // =========================================================
    // COMPANY BRAND
    // =========================================================
    const COMPANY = {
      name: "CÔNG TY TNHH MTV TM - DV THƯỢNG HẢO",
      address: "ĐC: 96/3 KP. Thạnh Lợi, Phường Thuận An, Tp Hồ Chí Minh, Việt Nam",
    };

    // =========================================================
    // BORDERS / ALIGNMENTS
    // =========================================================
    const BORDER_THIN = {
      top: { style: "thin" },
      left: { style: "thin" },
      bottom: { style: "thin" },
      right: { style: "thin" },
    };

    const BORDER_TOP_MEDIUM = (base = BORDER_THIN) => ({
      ...base,
      top: { style: "medium" },
    });

    const ALN_C_M = { horizontal: "center", vertical: "middle" };
    const ALN_L_M = { horizontal: "left", vertical: "middle" };
    const ALN_L_M_WRAP = { horizontal: "left", vertical: "middle", wrapText: true };

    // =========================================================
    // FONTS
    // =========================================================
    const FONT_12 = { name: "Times New Roman", size: 12 };
    const FONT_12_I = { name: "Times New Roman", size: 12, italic: true };
    const FONT_14_B = { name: "Times New Roman", size: 14, bold: true };
    const FONT_20_B = { name: "Times New Roman", size: 20, bold: true };
    const FONT_T14 = { name: "Times New Roman", size: 14 };
    const FONT_T14_B = { name: "Times New Roman", size: 14, bold: true };
    const FONT_HDR_16_B = { name: "Times New Roman", size: 16, bold: true };

    // =========================================================
    // ROW HEIGHTS
    // =========================================================
    const ROW_H_NORMAL = 28;
    const ROW_H_WRAP2 = 44;
    const ROW_H_WRAP3 = 60;
    const ROW_H_HEADER_16 = 28;

    // =========================================================
    // FILLS
    // =========================================================
    const ZEBRA_FILL = { type: "pattern", pattern: "solid", fgColor: { argb: "FFF2F2F2" } };
    const BAND_FILL = { type: "pattern", pattern: "solid", fgColor: { argb: "FFDCDCDC" } };

    // =========================================================
    // HELPERS
    // =========================================================
    const toNum = (v, fallback = 999999) => {
      const x = Number(v);
      return Number.isFinite(x) ? x : fallback;
    };

    const fmtQty = (n) => {
      const x = Number(n || 0);
      if (!Number.isFinite(x)) return 0;
      return Math.round(x) === x ? x : Math.round(x * 10) / 10;
    };

    const fmtDateDMYDash = (d) => {
      if (!d) return null;

      const s = String(d);
      const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(s);
      if (m) return `${m[3]}-${m[2]}-${m[1]}`;

      const x = new Date(d);
      if (!isNaN(x)) {
        const dd = String(x.getDate()).padStart(2, "0");
        const mm = String(x.getMonth() + 1).padStart(2, "0");
        const yyyy = x.getFullYear();
        return `${dd}-${mm}-${yyyy}`;
      }

      return s;
    };

    const dmyToTs = (s) => {
      const m = /^(\d{2})-(\d{2})-(\d{4})$/.exec(String(s || ""));
      if (!m) return Number.POSITIVE_INFINITY;
      return new Date(`${m[3]}-${m[2]}-${m[1]}T00:00:00`).getTime();
    };

    const groupBy = (arr, keyFn) => {
      const map = new Map();
      for (const r of arr) {
        const k = keyFn(r);
        if (!map.has(k)) map.set(k, []);
        map.get(k).push(r);
      }
      return map;
    };

    const slugSafe = (s) => String(s || "").replace(/[\/\\:*?"<>|]/g, "_").trim();

    const shortSheetName = (s, max = 31) => {
      const clean = String(s || "").replace(/[\[\]\*\/\\\?\:]/g, "_").trim();
      return clean.length <= max ? clean : clean.slice(0, max);
    };

    const normalizeRows = (d) => {
      if (Array.isArray(d)) return d;

      try {
        if (typeof formatDataAsArray === "function") {
          return formatDataAsArray(d || {});
        }
      } catch (_) {}

      if (d && typeof d === "object") {
        const keys = Object.keys(d);
        if (!keys.length) return [];
        const n = d[keys[0]]?.length ?? 0;
        const rows = [];
        for (let i = 0; i < n; i++) {
          const row = {};
          for (const k of keys) row[k] = d[k]?.[i];
          rows.push(row);
        }
        return rows;
      }
      return [];
    };

    const cleanText = (v) => String(v ?? "").trim();

    const entityLabelOf = (r) => cleanText(r?.entity_name || "");
    const entityOrderOf = (r) => toNum(r?.entity_display_order, 999999);
    const entityKeyOf = (r) =>
      cleanText(r?.entity_key || "") ||
      `NAME:${entityLabelOf(r)}`;
    const entityTypeOf = (r) => cleanText(r?.entity_type || "");
    const entityNumericIdOf = (r) =>
      r?.entity_numeric_id == null || r?.entity_numeric_id === "" ? null
        : Number(r.entity_numeric_id);
    const entityLegacyIdOf = (r) =>
      r?.entity_id_legacy == null || r?.entity_id_legacy === "" ? null
        : Number(r.entity_id_legacy);

    const forceWrapText = (text) => {
      return String(text || "").trim().replace(/\s+/g, " ");
    };

    const estimateRowHeight = (...texts) => {
      let maxLines = 1;

      for (const t of texts) {
        const s = String(t || "");

        const explicitLines = s.split("\n").length;
        const approxWrappedLines = Math.max(
          1,
          ...s.split("\n").map((part) => Math.ceil((part || "").length / 18))
        );

        const lines = Math.max(explicitLines, approxWrappedLines);
        if (lines > maxLines) maxLines = lines;
      }

      if (maxLines <= 1) return ROW_H_NORMAL;
      if (maxLines === 2) return ROW_H_WRAP2;
      return ROW_H_WRAP3;
    };

    // Excel does not auto-fit merged rows. Measure against their actual width.
    let textMeasureContext;
    const estimateWrappedRowHeight = (ws, text, firstColumn, lastColumn, font) => {
      const size = Number(font?.size) || 14;
      let widthPx = 0;
      for (let col = firstColumn; col <= lastColumn; col++) {
        const column = ws.getColumn(col);
        if (column.hidden) continue;
        const width = Number(column.width ?? ws.properties?.defaultColWidth ?? 8.43);
        widthPx += Math.max(0, Math.floor(width * 7 + 5));
      }
      // Cell padding plus a small allowance for Excel/browser font differences.
      const availablePx = Math.max(1, (widthPx - 12) * 0.96);

      if (textMeasureContext === undefined) {
        try {
          textMeasureContext = document.createElement("canvas").getContext("2d");
        } catch (_) {
          textMeasureContext = null;
        }
      }
      if (textMeasureContext) {
        textMeasureContext.font = `${font?.bold ? "bold " : ""}${size}pt "${font?.name || "Times New Roman"}"`;
      }
      const measure = (value) => {
        if (textMeasureContext) return textMeasureContext.measureText(value).width;
        // Conservative fallback for a sandbox without a canvas context.
        let units = 0;
        for (const ch of String(value).normalize("NFC")) {
          if (/\p{M}/u.test(ch)) continue;
          units += /\s/.test(ch) ? 0.25
            : /[ilI.,:;!'|]/.test(ch) ? 0.28
            : /[MWmw]/.test(ch) ? 0.94
            : ch === ch.toUpperCase() ? 0.70 : 0.52;
        }
        return units * size * (4 / 3) * (font?.bold ? 1.08 : 1);
      };

      let lines = 0;
      for (const paragraph of String(text ?? "").split(/\r?\n/)) {
        let line = "";
        for (const word of paragraph.trim().split(/\s+/).filter(Boolean)) {
          const candidate = line ? `${line} ${word}` : word;
          if (measure(candidate) <= availablePx) {
            line = candidate;
            continue;
          }
          if (line) { lines++; line = ""; }
          // Also support a name/token that is wider than the cell by itself.
          for (const ch of word) {
            if (line && measure(line + ch) > availablePx) {
              lines++;
              line = "";
            }
            line += ch;
          }
        }
        lines++;
      }
      const lineHeight = Math.max(ROW_H_WRAP2 - ROW_H_NORMAL, Math.ceil(size * 1.1));
      return ROW_H_NORMAL + (Math.max(1, lines) - 1) * lineHeight;
    };

    const styleRowRange = (ws, rowNum, cols, { font, alignment, border, fill } = {}) => {
      for (const col of cols) {
        const cell = ws.getCell(`${col}${rowNum}`);
        if (font) cell.font = font;
        if (alignment) cell.alignment = alignment;
        if (border) cell.border = border;
        if (fill) cell.fill = fill;
      }
    };

    // =========================================================
    // LOGO
    // =========================================================
    const resolveLogoBase64 = (input) => {
      const raw =
        input && typeof input === "object" && "value" in input ? input.value : input;
      if (!raw || typeof raw !== "string") return null;

      const m = /^data:image\/(png|jpe?g);base64,(.*)$/i.exec(raw);
      if (m) {
        return {
          base64: m[2],
          ext: m[1].toLowerCase() === "jpeg" ? "jpg" : m[1].toLowerCase(),
        };
      }

      const head = raw.slice(0, 10);
      if (head.startsWith("iVBORw0KG")) return { base64: raw, ext: "png" };
      if (head.startsWith("/9j/")) return { base64: raw, ext: "jpg" };
      return { base64: raw, ext: "png" };
    };

    const compressLogoToJpgDataUrl = async (inputDataUrl, targetWidth = 600, quality = 0.75) =>
      new Promise((resolve, reject) => {
        const img = new Image();
        img.onload = () => {
          const w = Math.min(targetWidth, img.width || targetWidth);
          const h = Math.round((img.height || w) * (w / (img.width || w)));
          const canvas = document.createElement("canvas");
          canvas.width = w;
          canvas.height = h;
          const ctx = canvas.getContext("2d");
          ctx.fillStyle = "#FFFFFF";
          ctx.fillRect(0, 0, w, h);
          ctx.drawImage(img, 0, 0, w, h);
          resolve(canvas.toDataURL("image/jpeg", quality));
        };
        img.onerror = reject;
        img.src = inputDataUrl;
      });

    const rawLogo = typeof logoBase64 === "undefined" ? null : logoBase64;
    const rawLogoDataUrl =
      rawLogo && typeof rawLogo === "object" && "value" in rawLogo ? rawLogo.value : rawLogo;

    if (!rawLogoDataUrl) {
      utils.showNotification({ title: "Không tìm thấy logo", type: "error" });
      return;
    }

    let compressedLogoDataUrl;
    try {
      const isDataUrl = /^data:image\//i.test(rawLogoDataUrl);
      const wrapped = isDataUrl ? rawLogoDataUrl : `data:image/png;base64,${rawLogoDataUrl}`;
      compressedLogoDataUrl = await compressLogoToJpgDataUrl(wrapped, 600, 0.75);
    } catch {
      compressedLogoDataUrl = rawLogoDataUrl;
    }

    const logoResolved = resolveLogoBase64(compressedLogoDataUrl);
    if (!logoResolved || !logoResolved.base64) {
      utils.showNotification({ title: "Không đọc được logo", type: "error" });
      return;
    }

    // =========================================================
    // INPUTS
    // =========================================================
    utils.showNotification({
      title: `Đang xuất PO nhóm (${mode})...`,
      type: "info",
    });

    const aggRaw = normalizeRows(q_po_grouped_supplier_agg_from_po.data);
    const schoolRaw = normalizeRows(q_po_grouped_school_breakdown_from_po.data);
    const ingRaw = normalizeRows(q_po_grouped_ingredient_breakdown_from_po.data);

    if (!aggRaw.length && !schoolRaw.length && !ingRaw.length) {
      utils.showNotification({
        title: "Không có dữ liệu PO nhóm để xuất",
        description: "Chưa có dữ liệu grouped PO cho khoảng ngày đã chọn.",
        type: "warning",
      });
      return;
    }

    const start = fmtDateDMYDash(PO_datepicker.value.start);
    const end = fmtDateDMYDash(PO_datepicker.value.end);

    // =========================================================
    // NORMALIZE SOURCE ROWS
    // =========================================================
    const aggRows0 = aggRaw
      .map((x) => ({
        ...x,
        service_date: fmtDateDMYDash(x.service_date),
        supplier_id: x.supplier_id,
        supplier_name: cleanText(x.supplier_name),

        entity_type: entityTypeOf(x),
        entity_key: entityKeyOf(x),
        entity_numeric_id: entityNumericIdOf(x),
        entity_id_legacy: entityLegacyIdOf(x),
        entity_name: entityLabelOf(x),
        entity_display_order: entityOrderOf(x),

        ingredient_id: x.ingredient_id,
        ingredient_name: cleanText(x.ingredient_name),
        purchase_unit: cleanText(x.purchase_unit),
        note: cleanText(x.note),
        qty_total: Number(x.qty_total || 0),
        shopping_type_id: toNum(x.shopping_type_id, 999999),
      }))
      .filter((x) => x.supplier_id != null && x.service_date);

    const schoolRows0 = schoolRaw
      .map((x) => ({
        ...x,
        service_date: fmtDateDMYDash(x.service_date),
        supplier_id: x.supplier_id,
        supplier_name: cleanText(x.supplier_name),

        entity_type: entityTypeOf(x),
        entity_key: entityKeyOf(x),
        entity_numeric_id: entityNumericIdOf(x),
        entity_id_legacy: entityLegacyIdOf(x),
        entity_name: entityLabelOf(x),
        entity_display_order: entityOrderOf(x),

        ingredient_id: x.ingredient_id,
        ingredient_name: cleanText(x.ingredient_name),
        purchase_unit: cleanText(x.purchase_unit),
        note: cleanText(x.note),
        qty: Number(x.qty || 0),
        shopping_type_id: toNum(x.shopping_type_id, 999999),
      }))
      .filter((x) => x.supplier_id != null && x.service_date);

    const ingRows0 = ingRaw
      .map((x) => ({
        ...x,
        service_date: fmtDateDMYDash(x.service_date),
        supplier_id: x.supplier_id,
        supplier_name: cleanText(x.supplier_name),

        entity_type: entityTypeOf(x),
        entity_key: entityKeyOf(x),
        entity_numeric_id: entityNumericIdOf(x),
        entity_id_legacy: entityLegacyIdOf(x),
        entity_name: entityLabelOf(x),
        entity_display_order: entityOrderOf(x),

        ingredient_id: x.ingredient_id,
        ingredient_name: cleanText(x.ingredient_name),
        purchase_unit: cleanText(x.purchase_unit),
        note: cleanText(x.note),
        qty: Number(x.qty || 0),
      }))
      .filter((x) => x.supplier_id != null && x.service_date);

    // =========================================================
    // DEFENSIVE RE-AGGREGATION
    // =========================================================
    const aggregateRows = (rows, cfg) => {
      const map = new Map();

      for (const r of rows || []) {
        const key = cfg.keyFn(r);
        let v = map.get(key);

        if (!v) {
          v = cfg.seedFn(r);
          map.set(key, v);
        }

        cfg.addFn(v, r);
      }

      return [...map.values()];
    };

    // SUM sheet grain:
    // supplier × date × entity_key × ingredient × unit × note
    // => NO school breakdown inside grouped entity
    const aggRows = aggregateRows(aggRows0, {
      keyFn: (r) => [
        r.supplier_id,
        r.service_date,
        r.entity_key || r.entity_name,
        r.ingredient_id,
        r.purchase_unit,
        r.note,
      ].join("||"),
      seedFn: (r) => ({
        supplier_id: r.supplier_id,
        supplier_name: r.supplier_name,
        service_date: r.service_date,

        entity_type: r.entity_type,
        entity_key: r.entity_key,
        entity_numeric_id: r.entity_numeric_id,
        entity_id_legacy: r.entity_id_legacy,
        entity_name: r.entity_name,
        entity_display_order: r.entity_display_order,

        ingredient_id: r.ingredient_id,
        shopping_type_id: r.shopping_type_id,
        ingredient_name: r.ingredient_name,
        purchase_unit: r.purchase_unit,
        note: r.note,
        qty_total: 0,
      }),
      addFn: (v, r) => {
        v.qty_total += Number(r.qty_total || 0);
        v.entity_display_order = Math.min(
          toNum(v.entity_display_order),
          toNum(r.entity_display_order)
        );
        v.shopping_type_id = Math.min(
          toNum(v.shopping_type_id),
          toNum(r.shopping_type_id)
        );
        if (!v.supplier_name && r.supplier_name) v.supplier_name = r.supplier_name;
        if (!v.entity_name && r.entity_name) v.entity_name = r.entity_name;
        if (!v.entity_key && r.entity_key) v.entity_key = r.entity_key;
        if (!v.entity_type && r.entity_type) v.entity_type = r.entity_type;
        if (v.entity_numeric_id == null && r.entity_numeric_id != null) {
          v.entity_numeric_id = r.entity_numeric_id;
        }
        if (v.entity_id_legacy == null && r.entity_id_legacy != null) {
          v.entity_id_legacy = r.entity_id_legacy;
        }
      },
    });

    // school detail sheet grain:
    // supplier × date × entity_key × ingredient × unit × note
    const schoolRows = aggregateRows(schoolRows0, {
      keyFn: (r) => [
        r.supplier_id,
        r.service_date,
        r.entity_key || r.entity_name,
        r.ingredient_id,
        r.purchase_unit,
        r.note,
      ].join("||"),
      seedFn: (r) => ({
        supplier_id: r.supplier_id,
        supplier_name: r.supplier_name,
        service_date: r.service_date,

        entity_type: r.entity_type,
        entity_key: r.entity_key,
        entity_numeric_id: r.entity_numeric_id,
        entity_id_legacy: r.entity_id_legacy,
        entity_name: r.entity_name,
        entity_display_order: r.entity_display_order,

        ingredient_id: r.ingredient_id,
        shopping_type_id: r.shopping_type_id,
        ingredient_name: r.ingredient_name,
        purchase_unit: r.purchase_unit,
        note: r.note,
        qty: 0,
      }),
      addFn: (v, r) => {
        v.qty += Number(r.qty || 0);
        v.entity_display_order = Math.min(
          toNum(v.entity_display_order),
          toNum(r.entity_display_order)
        );
        v.shopping_type_id = Math.min(
          toNum(v.shopping_type_id),
          toNum(r.shopping_type_id)
        );
        if (!v.supplier_name && r.supplier_name) v.supplier_name = r.supplier_name;
        if (!v.entity_name && r.entity_name) v.entity_name = r.entity_name;
        if (!v.entity_key && r.entity_key) v.entity_key = r.entity_key;
        if (!v.entity_type && r.entity_type) v.entity_type = r.entity_type;
        if (v.entity_numeric_id == null && r.entity_numeric_id != null) {
          v.entity_numeric_id = r.entity_numeric_id;
        }
        if (v.entity_id_legacy == null && r.entity_id_legacy != null) {
          v.entity_id_legacy = r.entity_id_legacy;
        }
      },
    });

    // ingredient detail sheet grain:
    // supplier × date × ingredient × unit × note × entity_key
    const ingRows = aggregateRows(ingRows0, {
      keyFn: (r) => [
        r.supplier_id,
        r.service_date,
        r.ingredient_id,
        r.purchase_unit,
        r.note,
        r.entity_key || r.entity_name,
      ].join("||"),
      seedFn: (r) => ({
        supplier_id: r.supplier_id,
        supplier_name: r.supplier_name,
        service_date: r.service_date,

        ingredient_id: r.ingredient_id,
        ingredient_name: r.ingredient_name,
        purchase_unit: r.purchase_unit,
        note: r.note,

        entity_type: r.entity_type,
        entity_key: r.entity_key,
        entity_numeric_id: r.entity_numeric_id,
        entity_id_legacy: r.entity_id_legacy,
        entity_name: r.entity_name,
        entity_display_order: r.entity_display_order,

        qty: 0,
      }),
      addFn: (v, r) => {
        v.qty += Number(r.qty || 0);
        v.entity_display_order = Math.min(
          toNum(v.entity_display_order),
          toNum(r.entity_display_order)
        );
        if (!v.supplier_name && r.supplier_name) v.supplier_name = r.supplier_name;
        if (!v.entity_name && r.entity_name) v.entity_name = r.entity_name;
        if (!v.entity_key && r.entity_key) v.entity_key = r.entity_key;
        if (!v.entity_type && r.entity_type) v.entity_type = r.entity_type;
        if (v.entity_numeric_id == null && r.entity_numeric_id != null) {
          v.entity_numeric_id = r.entity_numeric_id;
        }
        if (v.entity_id_legacy == null && r.entity_id_legacy != null) {
          v.entity_id_legacy = r.entity_id_legacy;
        }
      },
    });

    // =========================================================
    // OPTIONAL DEBUG
    // =========================================================
    console.log("PO GROUPED DEBUG S:21 agg", aggRows.filter((r) => String(r.entity_key) === "S:21"));
    console.log("PO GROUPED DEBUG G:21 agg", aggRows.filter((r) => String(r.entity_key) === "G:21"));

    // =========================================================
    // SUPPLIER NAME MAP
    // =========================================================
    const supplierNameById = new Map();
    for (const r of [...aggRows, ...schoolRows, ...ingRows]) {
      if (r?.supplier_id != null && r?.supplier_name) {
        supplierNameById.set(String(r.supplier_id), String(r.supplier_name));
      }
    }

    // =========================================================
    // SHEET SETUP
    // =========================================================
    const applyA4PortraitOnePage = (ws) => {
      ws.pageSetup = {
        paperSize: 9,
        orientation: "portrait",
        fitToPage: true,
        fitToWidth: 1,
        fitToHeight: 0,
        margins: { left: 0.3, right: 0.3, top: 0.4, bottom: 0.5, header: 0.2, footer: 0.2 },
      };
      ws.properties.defaultRowHeight = 20;
    };

    const drawBrandHeader = (ws, logoId) => {
      ws.addImage(logoId, { tl: { col: 0.06, row: 0.2 }, ext: { width: 100, height: 58 } });

      ws.mergeCells("C1:F1");
      ws.getCell("C1").value = COMPANY.name;
      ws.getCell("C1").alignment = ALN_L_M;
      ws.getCell("C1").font = FONT_14_B;

      ws.mergeCells("C2:F2");
      ws.getCell("C2").value = COMPANY.address;
      ws.getCell("C2").alignment = { horizontal: "left", vertical: "middle", shrinkToFit: true, wrapText: false };
      ws.getCell("C2").font = FONT_12_I;

      ws.getRow(1).height = 22;
      ws.getRow(2).height = 18;
      ws.getRow(3).height = 8;
    };

    const putRightDate = (ws, dateDMYDash) => {
      ws.getCell("E5").value = "Ngày dùng:";
      ws.getCell("E5").alignment = { horizontal: "right", vertical: "middle" };
      ws.getCell("E5").font = FONT_HDR_16_B;

      ws.getCell("F5").value = dateDMYDash.replace(/-/g, "/");
      ws.getCell("F5").alignment = { horizontal: "left", vertical: "middle" };
      ws.getCell("F5").font = FONT_HDR_16_B;
    };

    // =========================================================
    // SUMMARY HEADER
    // =========================================================
    const drawSummaryHeader = (ws, logoId, dateDMYDash, supName, supId) => {
      applyA4PortraitOnePage(ws);
      ws.columns = [
        { width: 7 },
        { width: 12 },
        { width: 36 },
        { width: 9 },
        { width: 11 },
        { width: 14 },
      ];

      drawBrandHeader(ws, logoId);

      ws.mergeCells("A4:F4");
      ws.getCell("A4").value = "PHIẾU ĐẶT HÀNG";
      ws.getCell("A4").alignment = ALN_C_M;
      ws.getCell("A4").font = FONT_20_B;

      putRightDate(ws, dateDMYDash);

      ws.mergeCells("A6:C6");
      ws.getCell("A6").value = {
        richText: [
          { text: "Nhà cung cấp: ", font: FONT_12 },
          { text: String(supName ?? ""), font: FONT_HDR_16_B },
        ],
      };
      ws.getCell("A6").alignment = ALN_L_M;
      ws.getRow(6).height = 24;

      ws.mergeCells("A7:C7");
      ws.getCell("A7").value = {
        richText: [
          { text: "Mã NCC: ", font: FONT_12 },
          { text: String(supId ?? ""), font: FONT_HDR_16_B },
        ],
      };
      ws.getCell("A7").alignment = ALN_L_M;
      ws.getRow(7).height = 24;

      ws.getRow(9).values = ["STT", "Mã hàng", "Tên hàng", "Đơn vị", "Số lượng", "Ghi chú"];
      ws.getRow(9).height = ROW_H_HEADER_16;

      for (let c = 1; c <= 6; c++) {
        const cell = ws.getCell(9, c);
        cell.border = BORDER_THIN;
        cell.alignment = ALN_C_M;
        cell.font = FONT_HDR_16_B;
      }
    };

    const drawDetailHeaderCommon = (ws, logoId, title, dateDMYDash, supName) => {
      applyA4PortraitOnePage(ws);
      ws.columns = [
        { width: 15 },
        { width: 13 },
        { width: 8 },
        { width: 34 },
        { width: 11 },
        { width: 9 },
        { width: 12 },
      ];

      ws.addImage(logoId, { tl: { col: 0.10, row: 0.20 }, ext: { width: 100, height: 58 } });

      ws.mergeCells("B1:G1");
      ws.getCell("B1").value = COMPANY.name;
      ws.getCell("B1").alignment = ALN_L_M;
      ws.getCell("B1").font = FONT_14_B;

      ws.mergeCells("B2:G2");
      ws.getCell("B2").value = COMPANY.address;
      ws.getCell("B2").alignment = { horizontal: "left", vertical: "middle", shrinkToFit: true, wrapText: false };
      ws.getCell("B2").font = FONT_12_I;

      ws.getRow(1).height = 22;
      ws.getRow(2).height = 18;
      ws.getRow(3).height = 8;

      ws.mergeCells("A4:G4");
      ws.getCell("A4").value = title;
      ws.getCell("A4").alignment = ALN_C_M;
      ws.getCell("A4").font = FONT_20_B;

      ws.getCell("E5").value = "Ngày dùng:";
      ws.getCell("E5").alignment = { horizontal: "right", vertical: "middle" };
      ws.getCell("E5").font = FONT_HDR_16_B;

      ws.getCell("F5").value = dateDMYDash.replace(/-/g, "/");
      ws.getCell("F5").alignment = { horizontal: "left", vertical: "middle" };
      ws.getCell("F5").font = FONT_HDR_16_B;

      ws.mergeCells("A6:D6");
      ws.getCell("A6").value = {
        richText: [
          { text: "Nhà cung cấp: ", font: FONT_12 },
          { text: String(supName ?? ""), font: FONT_HDR_16_B },
        ],
      };
      ws.getCell("A6").alignment = ALN_L_M;
      ws.getRow(6).height = 24;
    };

    const buildGroupedSummarySheet = (ws, logoId, dateDMYDash, supName, supId, rows) => {
  drawSummaryHeader(ws, logoId, dateDMYDash, supName, supId);

  let r = 10;

  // TRUE SUMMARY:
  // aggregate across ALL grouped entities for this supplier + date
  // grain = ingredient + unit + note only
  const summaryRows = aggregateRows(rows || [], {
    keyFn: (x) => [
      x.ingredient_id,
      cleanText(x.purchase_unit),
      cleanText(x.note),
    ].join("||"),
    seedFn: (x) => ({
      ingredient_id: x.ingredient_id,
      shopping_type_id: x.shopping_type_id,
      ingredient_name: x.ingredient_name,
      purchase_unit: x.purchase_unit,
      note: x.note,
      qty_total: 0,
    }),
    addFn: (v, x) => {
      v.qty_total += Number(x.qty_total || 0);
      v.shopping_type_id = Math.min(
        toNum(v.shopping_type_id, 999999),
        toNum(x.shopping_type_id, 999999)
      );
    },
  }).sort(
    (a, b) =>
      toNum(a.shopping_type_id, 999999) - toNum(b.shopping_type_id, 999999) ||
      cleanText(a.ingredient_name).localeCompare(cleanText(b.ingredient_name)) ||
      cleanText(a.purchase_unit).localeCompare(cleanText(b.purchase_unit)) ||
      cleanText(a.note).localeCompare(cleanText(b.note))
  );

  summaryRows.forEach((row, i) => {
    const ingName = forceWrapText(row.ingredient_name);
    const noteText = forceWrapText(row.note || "");

    ws.getRow(r).values = [
      i + 1,
      row.ingredient_id,
      ingName,
      row.purchase_unit,
      fmtQty(row.qty_total || 0),
      noteText,
    ];
    ws.getRow(r).height = estimateRowHeight(ingName, noteText);

    for (let c = 1; c <= 6; c++) {
      const cell = ws.getCell(r, c);
      cell.border = BORDER_THIN;
      cell.font = FONT_T14;
    }

    ws.getCell(`A${r}`).alignment = ALN_C_M;
    ws.getCell(`B${r}`).alignment = ALN_C_M;
    ws.getCell(`C${r}`).alignment = ALN_L_M_WRAP;
    ws.getCell(`D${r}`).alignment = ALN_C_M;
    ws.getCell(`E${r}`).alignment = ALN_C_M;
    ws.getCell(`F${r}`).alignment = ALN_L_M_WRAP;

    if (i % 2 === 1) {
      for (const col of ["A", "B", "C", "D", "E", "F"]) {
        ws.getCell(`${col}${r}`).fill = ZEBRA_FILL;
      }
    }

    r++;
  });

  ws.pageSetup.printArea = `A1:F${Math.max(r - 1, 9)}`;
  ws.pageSetup.printTitlesRow = "1:9";
};
    const buildBreakdownByEntitySheet = (ws, logoId, dateDMYDash, supName, rows) => {
      drawDetailHeaderCommon(ws, logoId, "CHI TIẾT GIAO HÀNG", dateDMYDash, supName);

      ws.getRow(9).values = ["Trường học", null, "STT", "Tên hàng", "Đơn vị", "Số lượng", null];
      ws.getRow(9).height = ROW_H_HEADER_16;
      ws.mergeCells("A9:B9");
      ws.mergeCells("F9:G9");

      for (const addr of ["A9", "C9", "D9", "E9", "F9"]) {
        const cell = ws.getCell(addr);
        cell.alignment = ALN_C_M;
        cell.border = BORDER_THIN;
        cell.font = FONT_HDR_16_B;
      }

      let r = 10;

      const sorted = [...(rows || [])].sort(
        (a, b) =>
          entityOrderOf(a) - entityOrderOf(b) ||
          entityLabelOf(a).localeCompare(entityLabelOf(b)) ||
          toNum(a.shopping_type_id, 999999) - toNum(b.shopping_type_id, 999999) ||
          cleanText(a.ingredient_name).localeCompare(cleanText(b.ingredient_name)) ||
          cleanText(a.purchase_unit).localeCompare(cleanText(b.purchase_unit)) ||
          cleanText(a.note).localeCompare(cleanText(b.note))
      );

      const byEntity = groupBy(sorted, (x) => entityKeyOf(x));
      const entityKeys = [...byEntity.keys()].sort((ka, kb) => {
        const a0 = byEntity.get(ka)?.[0];
        const b0 = byEntity.get(kb)?.[0];
        return (
          entityOrderOf(a0) - entityOrderOf(b0) ||
          entityLabelOf(a0).localeCompare(entityLabelOf(b0)) ||
          String(ka).localeCompare(String(kb))
        );
      });

      for (const entityKey of entityKeys) {
        const list = byEntity.get(entityKey) || [];
        const entityName = forceWrapText(entityLabelOf(list[0]));

        ws.getRow(r).values = [entityName, null, null, null, null, null, null];
        ws.mergeCells(`A${r}:G${r}`);
        ws.getRow(r).height = estimateWrappedRowHeight(ws, entityName, 1, 7, FONT_T14_B);

        styleRowRange(ws, r, ["A", "B", "C", "D", "E", "F", "G"], {
          font: FONT_T14_B,
          alignment: ALN_L_M_WRAP,
          border: BORDER_TOP_MEDIUM(BORDER_THIN),
          fill: BAND_FILL,
        });
        r++;

        for (let i = 0; i < list.length; i++) {
          const it = list[i];
          const ingName = forceWrapText(it.ingredient_name);

          ws.getRow(r).values = [
            "",
            null,
            i + 1,
            ingName,
            it.purchase_unit,
            fmtQty(it.qty || 0),
            null,
          ];

          ws.mergeCells(`A${r}:B${r}`);
          ws.mergeCells(`F${r}:G${r}`);
          ws.getRow(r).height = estimateRowHeight(ingName);

          if (i % 2 === 1) {
            for (const col of ["A", "B", "C", "D", "E", "F", "G"]) {
              ws.getCell(`${col}${r}`).fill = ZEBRA_FILL;
            }
          }

          for (const col of ["A", "B", "C", "D", "E", "F", "G"]) {
            const cell = ws.getCell(`${col}${r}`);
            cell.border = BORDER_THIN;
            cell.font = FONT_T14;
          }

          ws.getCell(`C${r}`).alignment = ALN_C_M;
          ws.getCell(`D${r}`).alignment = ALN_L_M_WRAP;
          ws.getCell(`E${r}`).alignment = ALN_C_M;
          ws.getCell(`F${r}`).alignment = ALN_C_M;

          r++;
        }

        ws.getRow(r).height = 10;
        r++;
      }

      ws.pageSetup.printArea = `A1:G${r}`;
      ws.pageSetup.printTitlesRow = "1:9";
    };

    const buildBreakdownByIngredientSheet = (ws, logoId, dateDMYDash, supName, rows) => {
      drawDetailHeaderCommon(ws, logoId, "CHI TIẾT GIAO HÀNG (THEO HÀNG)", dateDMYDash, supName);

      ws.getRow(9).values = ["Tên hàng", null, "STT", "Trường học", "Đơn vị", "Số lượng", null];
      ws.getRow(9).height = ROW_H_HEADER_16;
      ws.mergeCells("A9:B9");
      ws.mergeCells("F9:G9");

      for (const addr of ["A9", "C9", "D9", "E9", "F9"]) {
        const cell = ws.getCell(addr);
        cell.alignment = ALN_C_M;
        cell.border = BORDER_THIN;
        cell.font = FONT_HDR_16_B;
      }

      let r = 10;

      const sorted = [...(rows || [])].sort(
        (a, b) =>
          cleanText(a.ingredient_name).localeCompare(cleanText(b.ingredient_name)) ||
          cleanText(a.purchase_unit).localeCompare(cleanText(b.purchase_unit)) ||
          cleanText(a.note).localeCompare(cleanText(b.note)) ||
          entityOrderOf(a) - entityOrderOf(b) ||
          entityLabelOf(a).localeCompare(entityLabelOf(b))
      );

      const byIngKey = groupBy(
        sorted,
        (x) => `${x.ingredient_id}||${cleanText(x.purchase_unit)}||${cleanText(x.note)}`
      );

      const ingKeys = [...byIngKey.keys()].sort((ka, kb) => {
        const a0 = byIngKey.get(ka)?.[0];
        const b0 = byIngKey.get(kb)?.[0];
        return (
          cleanText(a0?.ingredient_name).localeCompare(cleanText(b0?.ingredient_name)) ||
          cleanText(a0?.purchase_unit).localeCompare(cleanText(b0?.purchase_unit)) ||
          cleanText(a0?.note).localeCompare(cleanText(b0?.note))
        );
      });

      for (const ingKey of ingKeys) {
        const itemsRaw = byIngKey.get(ingKey) || [];
        const ingName = cleanText(itemsRaw?.[0]?.ingredient_name);
        const unit = cleanText(itemsRaw?.[0]?.purchase_unit);
        const note = cleanText(itemsRaw?.[0]?.note);

        const headerTextBase = note ? `${ingName} (${unit}) - ${note}`
          : `${ingName} (${unit})`;

        const headerText = forceWrapText(headerTextBase);

        ws.getRow(r).values = [headerText, null, null, null, null, null, null];
        ws.mergeCells(`A${r}:G${r}`);
        ws.getRow(r).height = estimateWrappedRowHeight(ws, headerText, 1, 7, FONT_T14_B);

        styleRowRange(ws, r, ["A", "B", "C", "D", "E", "F", "G"], {
          font: FONT_T14_B,
          alignment: ALN_L_M_WRAP,
          border: BORDER_TOP_MEDIUM(BORDER_THIN),
          fill: BAND_FILL,
        });
        r++;

        const items = [...itemsRaw].sort(
          (a, b) =>
            entityOrderOf(a) - entityOrderOf(b) ||
            entityLabelOf(a).localeCompare(entityLabelOf(b))
        );

        for (let i = 0; i < items.length; i++) {
          const it = items[i];
          const entityName = forceWrapText(entityLabelOf(it));

          ws.getRow(r).values = [
            "",
            null,
            i + 1,
            entityName,
            unit,
            fmtQty(it.qty || 0),
            null,
          ];

          ws.mergeCells(`A${r}:B${r}`);
          ws.mergeCells(`F${r}:G${r}`);
          ws.getRow(r).height = estimateWrappedRowHeight(ws, entityName, 4, 4, FONT_T14);

          if (i % 2 === 1) {
            for (const col of ["A", "B", "C", "D", "E", "F", "G"]) {
              ws.getCell(`${col}${r}`).fill = ZEBRA_FILL;
            }
          }

          for (const col of ["A", "B", "C", "D", "E", "F", "G"]) {
            const cell = ws.getCell(`${col}${r}`);
            cell.border = BORDER_THIN;
            cell.font = FONT_T14;
          }

          ws.getCell(`C${r}`).alignment = ALN_C_M;
          ws.getCell(`D${r}`).alignment = ALN_L_M_WRAP;
          ws.getCell(`E${r}`).alignment = ALN_C_M;
          ws.getCell(`F${r}`).alignment = ALN_C_M;

          r++;
        }

        ws.getRow(r).height = 10;
        r++;
      }

      ws.pageSetup.printArea = `A1:G${r}`;
      ws.pageSetup.printTitlesRow = "1:9";
    };

    // =========================================================
    // BUILD EXPORT BUCKETS
    // =========================================================
    const exportMap = new Map();

    const getBucket = (supplierId, serviceDate) => {
      if (supplierId == null || !serviceDate) return null;

      const key = `${supplierId}__${serviceDate}`;
      let bucket = exportMap.get(key);

      if (!bucket) {
        bucket = {
          supplier_id: supplierId,
          service_date: serviceDate,
          totals: [],
          schoolDetails: [],
          ingredientDetails: [],
        };
        exportMap.set(key, bucket);
      }

      return bucket;
    };

    for (const r of aggRows) {
      const bucket = getBucket(r.supplier_id, r.service_date);
      if (bucket) bucket.totals.push(r);
    }

    for (const r of schoolRows) {
      const bucket = getBucket(r.supplier_id, r.service_date);
      if (bucket) bucket.schoolDetails.push(r);
    }

    for (const r of ingRows) {
      const bucket = getBucket(r.supplier_id, r.service_date);
      if (bucket) bucket.ingredientDetails.push(r);
    }

    const exportUnits = [...exportMap.values()]
      .filter((u) => u.totals.length || u.schoolDetails.length || u.ingredientDetails.length)
      .sort((a, b) => {
        const da = dmyToTs(a.service_date);
        const db = dmyToTs(b.service_date);
        if (da !== db) return da - db;

        const sa = String(supplierNameById.get(String(a.supplier_id)) || `NCC ${a.supplier_id}`);
        const sb = String(supplierNameById.get(String(b.supplier_id)) || `NCC ${b.supplier_id}`);
        return sa.localeCompare(sb);
      });

    if (!exportUnits.length) {
      utils.showNotification({
        title: "Không có dữ liệu để xuất",
        description: "Không tìm thấy cặp NCC + ngày trong grouped PO.",
        type: "warning",
      });
      return;
    }

    // =========================================================
    // BUILD ZIP: one workbook per supplier, all dates inside that workbook.
    // exportUnits are already sorted chronologically.
    // =========================================================
    const zip = new JSZip();
    const unitsBySupplier = groupBy(exportUnits, (unit) => String(unit.supplier_id));

    const supplierFiles = await Promise.all(
      [...unitsBySupplier.values()].map(async (supplierUnits) => {
        const supId = supplierUnits[0].supplier_id;
        const supDisplay = String(supplierNameById.get(String(supId)) || `NCC ${supId}`);

        const wb = new ExcelJS.Workbook();
        const logoId = wb.addImage({
          base64: logoResolved.base64,
          extension: logoResolved.ext,
        });

        for (const unit of supplierUnits) {
          const date = unit.service_date;

          if (INCLUDE.detailsIng) {
            const wsCtIng = wb.addWorksheet(shortSheetName(`${date} - Theo hàng`), {
              views: [{ showGridLines: false }],
            });
            buildBreakdownByIngredientSheet(
              wsCtIng,
              logoId,
              date,
              supDisplay,
              unit.ingredientDetails
            );
          }

          if (INCLUDE.detailsSchool) {
            const wsCt = wb.addWorksheet(shortSheetName(`${date} - Theo trường`), {
              views: [{ showGridLines: false }],
            });
            buildBreakdownByEntitySheet(
              wsCt,
              logoId,
              date,
              supDisplay,
              unit.schoolDetails
            );
          }

          if (INCLUDE.sum) {
            const wsTong = wb.addWorksheet(shortSheetName(`${date} - Tổng`), {
              views: [{ showGridLines: false }],
            });
            buildGroupedSummarySheet(
              wsTong,
              logoId,
              date,
              supDisplay,
              supId,
              unit.totals
            );
          }
        }

        const buf = await wb.xlsx.writeBuffer();

        const suffix =
          mode === "details_ing" ? "THEO_HANG_GROUPED"
            : mode === "details_school" ? "THEO_TRUONG_GROUPED"
              : mode === "sum" ? "TONG_GROUPED"
                : "ALL_GROUPED";

        const fileName = `${slugSafe(supDisplay)}_NCC${supId}_${slugSafe(start)}_${slugSafe(end)}_${suffix}.xlsx`;
        return [fileName, buf];
      })
    );

    for (const [fname, buf] of supplierFiles) {
      zip.file(fname, buf);
    }

    utils.showNotification({
      title: "Đang nén file ZIP...",
      type: "info",
    });

    const blob = await zip.generateAsync({ type: "blob" });
    utils.downloadFile(blob, `PO_GROUPED_${start}_${end}.zip`);

    utils.showNotification({
      title: "Tải xuống thành công!",
      description: `Đã tạo ${supplierFiles.length} file grouped XLSX (mỗi file = 1 NCC, gồm tất cả ngày có dữ liệu).`,
      type: "success",
    });
  } catch (err) {
    console.error(err);
    utils.showNotification({
      title: "Lỗi khi xuất grouped XLSX",
      description: String(err?.message || err),
      type: "error",
    });
  }
})();
